"""Lexer and recursive-descent parser for minisql ``SELECT`` queries.

``parse(sql)`` returns a ``nodes.Query``; any syntax error raises
``QueryError``. Every expression node's ``text`` is the exact slice of the
source covering that expression (including surrounding parentheses for a
parenthesized expression).
"""

from dataclasses import replace
from typing import List, NamedTuple, Optional

from . import nodes
from .errors import QueryError

__all__ = ["parse"]

KEYWORDS = frozenset("""
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
""".split())

# Token kinds
KEYWORD = "keyword"
NAME = "name"        # identifier (quoted or not); value is the unquoted name
INTEGER = "integer"
DECIMAL = "decimal"
STRING = "string"
OP = "op"
EOF = "end of query"

_OPERATORS = ("<=", ">=", "<>", "!=", "||", "=", "<", ">",
              "+", "-", "*", "/", "(", ")", ",", ";")

_COMPARISONS = ("=", "!=", "<>", "<", "<=", ">", ">=")


class Token(NamedTuple):
    kind: str
    value: object      # keyword (upper-case), name, number, string, or op
    start: int
    end: int
    quoted: bool = False  # for NAME: written in double quotes


def _is_ident_start(c):
    return c.isascii() and (c.isalpha() or c == "_")


def _is_ident_char(c):
    return c.isascii() and (c.isalnum() or c == "_")


def _describe_pos(sql, pos):
    return f"at position {pos + 1}"


def tokenize(sql: str) -> List[Token]:
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if _is_ident_start(c):
            while i < n and _is_ident_char(sql[i]):
                i += 1
            word = sql[start:i]
            if word.upper() in KEYWORDS:
                tokens.append(Token(KEYWORD, word.upper(), start, i))
            else:
                tokens.append(Token(NAME, word, start, i))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and sql[i + 1].isdigit()):
            while i < n and sql[i].isdigit():
                i += 1
            is_decimal = False
            if i < n and sql[i] == ".":
                is_decimal = True
                i += 1
                while i < n and sql[i].isdigit():
                    i += 1
            if i < n and (_is_ident_char(sql[i]) or sql[i] == "."):
                j = i
                while j < n and (_is_ident_char(sql[j]) or sql[j] == "."):
                    j += 1
                raise QueryError(
                    f"invalid number {sql[start:j]!r} "
                    f"{_describe_pos(sql, start)}")
            text = sql[start:i]
            if is_decimal:
                tokens.append(Token(DECIMAL, float(text), start, i))
            else:
                tokens.append(Token(INTEGER, int(text), start, i))
            continue
        if c == "'" or c == '"':
            quote = c
            i += 1
            parts = []
            while True:
                if i >= n:
                    what = "string" if quote == "'" else "quoted name"
                    raise QueryError(
                        f"unterminated {what} starting "
                        f"{_describe_pos(sql, start)}")
                if sql[i] == quote:
                    if i + 1 < n and sql[i + 1] == quote:
                        parts.append(quote)
                        i += 2
                        continue
                    i += 1
                    break
                parts.append(sql[i])
                i += 1
            value = "".join(parts)
            if quote == "'":
                tokens.append(Token(STRING, value, start, i))
            else:
                if value == "":
                    raise QueryError(
                        f"empty quoted name {_describe_pos(sql, start)}")
                tokens.append(Token(NAME, value, start, i, quoted=True))
            continue
        for op in _OPERATORS:
            if sql.startswith(op, i):
                i += len(op)
                tokens.append(Token(OP, op, start, i))
                break
        else:
            raise QueryError(
                f"unexpected character {c!r} {_describe_pos(sql, start)}")
    tokens.append(Token(EOF, None, n, n))
    return tokens


def _token_desc(tok: Token) -> str:
    if tok.kind == EOF:
        return "end of query"
    if tok.kind == KEYWORD:
        return f"keyword {tok.value}"
    if tok.kind == OP:
        return f"{tok.value!r}"
    return f"{tok.kind} {tok.value!r}" if tok.kind != NAME else f"name {tok.value!r}"


class _Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -----------------------------------------------------

    @property
    def tok(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset=1) -> Token:
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if tok.kind != EOF:
            self.pos += 1
        return tok

    def at_keyword(self, *words) -> bool:
        return self.tok.kind == KEYWORD and self.tok.value in words

    def at_op(self, *ops) -> bool:
        return self.tok.kind == OP and self.tok.value in ops

    def accept_keyword(self, word) -> Optional[Token]:
        if self.at_keyword(word):
            return self.advance()
        return None

    def accept_op(self, op) -> Optional[Token]:
        if self.at_op(op):
            return self.advance()
        return None

    def error(self, expected: str) -> QueryError:
        tok = self.tok
        return QueryError(
            f"syntax error: expected {expected}, got {_token_desc(tok)} "
            f"{_describe_pos(self.sql, tok.start)}")

    def expect_keyword(self, word) -> Token:
        if not self.at_keyword(word):
            raise self.error(word)
        return self.advance()

    def expect_op(self, op) -> Token:
        if not self.at_op(op):
            raise self.error(repr(op))
        return self.advance()

    def expect_name(self, what="a name") -> str:
        tok = self.tok
        if tok.kind != NAME:
            if tok.kind == KEYWORD:
                raise QueryError(
                    f"syntax error: expected {what}, got keyword {tok.value} "
                    f"{_describe_pos(self.sql, tok.start)} (keywords must be "
                    f"double-quoted to be used as names)")
            raise self.error(what)
        self.advance()
        return tok.value

    def text(self, start: int) -> str:
        """Source text from ``start`` to the end of the last consumed token."""
        end = self.tokens[self.pos - 1].end
        return self.sql[start:end]

    # -- query ---------------------------------------------------------------

    def parse_query(self) -> nodes.Query:
        if self.tok.kind == EOF:
            raise QueryError("empty query")
        self.expect_keyword("SELECT")
        distinct = self.accept_keyword("DISTINCT") is not None

        if self.accept_op("*"):
            columns = None
        else:
            items = [self.parse_select_item()]
            while self.accept_op(","):
                items.append(self.parse_select_item())
            columns = tuple(items)

        if not self.at_keyword("FROM"):
            raise self.error("FROM" if columns is None else "',' or FROM")
        self.advance()
        table = self.expect_name("a table name")

        where = None
        if self.accept_keyword("WHERE"):
            where = self.parse_expr()

        group_by = ()
        if self.accept_keyword("GROUP"):
            self.expect_keyword("BY")
            exprs = [self.parse_expr()]
            while self.accept_op(","):
                exprs.append(self.parse_expr())
            group_by = tuple(exprs)

        having = None
        if self.accept_keyword("HAVING"):
            having = self.parse_expr()

        order_by = ()
        if self.accept_keyword("ORDER"):
            self.expect_keyword("BY")
            items = [self.parse_order_item()]
            while self.accept_op(","):
                items.append(self.parse_order_item())
            order_by = tuple(items)

        limit = offset = None
        if self.accept_keyword("LIMIT"):
            limit = self.parse_count("LIMIT")
            if self.accept_keyword("OFFSET"):
                offset = self.parse_count("OFFSET")

        self.accept_op(";")
        if self.tok.kind != EOF:
            raise self.error("end of query")

        return nodes.Query(
            table=table, columns=columns, distinct=distinct, where=where,
            group_by=group_by, having=having, order_by=order_by,
            limit=limit, offset=offset)

    def parse_select_item(self) -> nodes.SelectItem:
        if self.at_op("*"):
            raise QueryError(
                f"syntax error: '*' must be the only column "
                f"{_describe_pos(self.sql, self.tok.start)}")
        expr = self.parse_expr()
        alias = None
        if self.accept_keyword("AS"):
            alias = self.expect_name("an alias after AS")
        elif self.tok.kind == NAME:
            alias = self.advance().value
        return nodes.SelectItem(expr, alias)

    def parse_order_item(self) -> nodes.OrderItem:
        expr = self.parse_expr()
        descending = False
        if self.accept_keyword("DESC"):
            descending = True
        else:
            self.accept_keyword("ASC")
        return nodes.OrderItem(expr, descending)

    def parse_count(self, clause) -> int:
        tok = self.tok
        if tok.kind != INTEGER:
            raise self.error(f"a non-negative integer after {clause}")
        self.advance()
        return tok.value

    # -- expressions -----------------------------------------------------------

    def parse_expr(self) -> nodes.Expr:
        return self.parse_or()

    def parse_or(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_and()
        while self.accept_keyword("OR"):
            right = self.parse_and()
            left = nodes.Binary("OR", left, right, text=self.text(start))
        return left

    def parse_and(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_not()
        while self.accept_keyword("AND"):
            right = self.parse_not()
            left = nodes.Binary("AND", left, right, text=self.text(start))
        return left

    def parse_not(self) -> nodes.Expr:
        start = self.tok.start
        if self.accept_keyword("NOT"):
            operand = self.parse_not()
            return nodes.Unary("NOT", operand, text=self.text(start))
        return self.parse_comparison()

    def parse_comparison(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_additive()
        result = self._comparison_suffix(left, start)
        if result is left:
            return left
        if self.at_op(*_COMPARISONS) or self.at_keyword(
                "IS", "IN", "BETWEEN", "LIKE") or (
                self.at_keyword("NOT") and self.peek().kind == KEYWORD
                and self.peek().value in ("IN", "BETWEEN", "LIKE")):
            raise QueryError(
                f"syntax error: comparisons can't be chained; use "
                f"parentheses or AND "
                f"{_describe_pos(self.sql, self.tok.start)}")
        return result

    def _comparison_suffix(self, left, start) -> nodes.Expr:
        if self.at_op(*_COMPARISONS):
            op = self.advance().value
            if op == "<>":
                op = "!="
            right = self.parse_additive()
            return nodes.Binary(op, left, right, text=self.text(start))

        if self.accept_keyword("IS"):
            negated = self.accept_keyword("NOT") is not None
            if not self.accept_keyword("NULL"):
                raise self.error("NULL" if negated else "NULL or NOT NULL")
            return nodes.IsNull(left, negated, text=self.text(start))

        negated = False
        if self.at_keyword("NOT"):
            nxt = self.peek()
            if nxt.kind == KEYWORD and nxt.value in ("IN", "BETWEEN", "LIKE"):
                self.advance()
                negated = True
            else:
                self.advance()
                raise self.error("IN, BETWEEN, or LIKE after NOT")

        if self.accept_keyword("IN"):
            self.expect_op("(")
            if self.at_op(")"):
                raise self.error("an expression (IN list can't be empty)")
            items = [self.parse_expr()]
            while self.accept_op(","):
                items.append(self.parse_expr())
            self.expect_op(")")
            return nodes.In(left, tuple(items), negated, text=self.text(start))

        if self.accept_keyword("BETWEEN"):
            low = self.parse_additive()
            self.expect_keyword("AND")
            high = self.parse_additive()
            return nodes.Between(left, low, high, negated,
                                 text=self.text(start))

        if self.accept_keyword("LIKE"):
            pattern = self.parse_additive()
            return nodes.Like(left, pattern, negated, text=self.text(start))

        return left

    def parse_additive(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            left = nodes.Binary(op, left, right, text=self.text(start))
        return left

    def parse_multiplicative(self) -> nodes.Expr:
        start = self.tok.start
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            right = self.parse_unary()
            left = nodes.Binary(op, left, right, text=self.text(start))
        return left

    def parse_unary(self) -> nodes.Expr:
        start = self.tok.start
        if self.accept_op("-"):
            operand = self.parse_unary()
            return nodes.Unary("-", operand, text=self.text(start))
        return self.parse_primary()

    def parse_primary(self) -> nodes.Expr:
        tok = self.tok
        start = tok.start
        if tok.kind in (INTEGER, DECIMAL, STRING):
            self.advance()
            return nodes.Literal(tok.value, text=self.text(start))
        if tok.kind == KEYWORD and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[tok.value]
            return nodes.Literal(value, text=self.text(start))
        if tok.kind == NAME:
            self.advance()
            if not tok.quoted and self.at_op("("):
                return self.parse_call(tok.value.upper(), start)
            return nodes.Column(tok.value, text=self.text(start))
        if self.accept_op("("):
            inner = self.parse_expr()
            self.expect_op(")")
            return replace(inner, text=self.text(start))
        if tok.kind == KEYWORD:
            raise QueryError(
                f"syntax error: expected an expression, got keyword "
                f"{tok.value} {_describe_pos(self.sql, tok.start)} (keywords "
                f"must be double-quoted to be used as names)")
        raise self.error("an expression")

    def parse_call(self, name, start) -> nodes.Call:
        self.expect_op("(")
        if self.at_op("*"):
            star_tok = self.advance()
            if name != "COUNT":
                raise QueryError(
                    f"syntax error: '*' is only allowed in COUNT(*), not "
                    f"{name} {_describe_pos(self.sql, star_tok.start)}")
            self.expect_op(")")
            return nodes.Call(name, (), star=True, text=self.text(start))
        args = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        return nodes.Call(name, tuple(args), text=self.text(start))


def parse(sql: str) -> nodes.Query:
    """Parse a minisql ``SELECT`` statement into a ``nodes.Query``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return _Parser(sql).parse_query()

